// Cryptographic mechanisms checked against published reference vectors.
//
// Vector sources (values are copied from the standards; nothing here was generated by this project):
//   SHA-256 "abc"          : FIPS 180-4 example / NIST CSRC "SHA-256 Example"
//   HMAC-SHA-256           : RFC 4231 section 4.2 (Test Case 1) and 4.3 (Test Case 2)
//   AES-128 block          : FIPS 197 Appendix C.1
//   AES-128-CBC            : NIST SP 800-38A section F.2.1 (CBC-AES128.Encrypt)
//   HKDF-SHA-256           : RFC 5869 Appendix A.1 (Test Case 1)
//   HMAC-SHA-256-128 trunc : RFC 4868 section 2.3 (ICV = first 128 bits of the HMAC output)
//
// As a second, independent check, results are also compared with Node's OpenSSL implementation.

import test from 'node:test';
import assert from 'node:assert/strict';
import nodeCrypto from 'node:crypto';
import {
  sha256, hmacSha256, computeIcv, aesCbcEncrypt, aesCbcDecrypt,
  generateEcdhKeyPair, ecdhSharedSecret, hkdfSha256, ALG,
} from '../src/engine/crypto.js';
import { fromHex, toHex, encoder, randomBytes } from '../src/engine/bytes.js';

test('SHA-256("abc") matches FIPS 180-4', async () => {
  assert.equal(
    toHex(await sha256(encoder.encode('abc'))),
    'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad',
  );
});

test('HMAC-SHA-256 RFC 4231 test case 1', async () => {
  const key = new Uint8Array(20).fill(0x0b);
  const mac = await hmacSha256(key, encoder.encode('Hi There'));
  assert.equal(toHex(mac), 'b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7');
});

test('HMAC-SHA-256 RFC 4231 test case 2', async () => {
  const mac = await hmacSha256(encoder.encode('Jefe'), encoder.encode('what do ya want for nothing?'));
  assert.equal(toHex(mac), '5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843');
});

test('ICV is HMAC-SHA-256 truncated to the leftmost 128 bits (RFC 4868)', async () => {
  const key = new Uint8Array(20).fill(0x0b);
  const icv = await computeIcv(key, encoder.encode('Hi There'));
  assert.equal(icv.length, 16);
  assert.equal(toHex(icv), 'b0344c61d8db38535ca8afceaf0bf12b');
});

test('ICV agrees with Node/OpenSSL HMAC for random inputs', async () => {
  for (let i = 0; i < 20; i++) {
    const key = randomBytes(32);
    const data = randomBytes(1 + Math.floor(Math.random() * 300));
    const ref = nodeCrypto.createHmac('sha256', key).update(data).digest().subarray(0, 16);
    assert.equal(toHex(await computeIcv(key, data)), ref.toString('hex'));
  }
});

test('AES-128 single block matches FIPS 197 Appendix C.1 (CBC with zero IV == ECB for one block)', async () => {
  const key = fromHex('000102030405060708090a0b0c0d0e0f');
  const pt = fromHex('00112233445566778899aabbccddeeff');
  const ct = await aesCbcEncrypt(key, new Uint8Array(16), pt);
  assert.equal(toHex(ct), '69c4e0d86a7b0430d8cdb78070b4c55a');
});

test('AES-128-CBC matches NIST SP 800-38A F.2.1 (two blocks)', async () => {
  const key = fromHex('2b7e151628aed2a6abf7158809cf4f3c');
  const iv = fromHex('000102030405060708090a0b0c0d0e0f');
  const pt = fromHex('6bc1bee22e409f96e93d7e117393172a' + 'ae2d8a571e03ac9c9eb76fac45af8e51');
  const ct = await aesCbcEncrypt(key, iv, pt);
  assert.equal(toHex(ct), '7649abac8119b246cee98e9b12e9197d' + '5086cb9b507219ee95db113a917678b2');
  assert.equal(toHex(await aesCbcDecrypt(key, iv, ct)), toHex(pt));
});

test('AES-CBC round trip and agreement with OpenSSL for random data', async () => {
  for (let i = 0; i < 20; i++) {
    const key = randomBytes(16);
    const iv = randomBytes(16);
    const pt = randomBytes(16 * (1 + Math.floor(Math.random() * 8)));
    const ct = await aesCbcEncrypt(key, iv, pt);
    const c = nodeCrypto.createCipheriv('aes-128-cbc', key, iv);
    c.setAutoPadding(false);
    const ref = Buffer.concat([c.update(pt), c.final()]);
    assert.equal(toHex(ct), ref.toString('hex'));
    assert.equal(toHex(await aesCbcDecrypt(key, iv, ct)), toHex(pt));
  }
});

test('same plaintext with different IVs gives different ciphertext', async () => {
  const key = randomBytes(16);
  const pt = randomBytes(32);
  const a = await aesCbcEncrypt(key, randomBytes(16), pt);
  const b = await aesCbcEncrypt(key, randomBytes(16), pt);
  assert.notEqual(toHex(a), toHex(b));
});

test('AES rejects bad key / IV / length', async () => {
  await assert.rejects(aesCbcEncrypt(randomBytes(15), randomBytes(16), randomBytes(16)), /16-byte key/);
  await assert.rejects(aesCbcEncrypt(randomBytes(16), randomBytes(8), randomBytes(16)), /16-byte IV/);
  await assert.rejects(aesCbcEncrypt(randomBytes(16), randomBytes(16), randomBytes(17)), /multiple of 16/);
  await assert.rejects(aesCbcDecrypt(randomBytes(16), randomBytes(16), new Uint8Array(0)), /multiple of 16/);
});

test('HKDF-SHA-256 matches RFC 5869 test case 1', async () => {
  const okm = await hkdfSha256(
    new Uint8Array(22).fill(0x0b),
    fromHex('000102030405060708090a0b0c'),
    fromHex('f0f1f2f3f4f5f6f7f8f9'),
    42,
  );
  assert.equal(
    toHex(okm),
    '3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865',
  );
});

test('ECDH P-256: both sides derive the same secret', async () => {
  const a = await generateEcdhKeyPair();
  const b = await generateEcdhKeyPair();
  assert.equal(a.publicRaw.length, 65);
  const s1 = await ecdhSharedSecret(a.privateKey, b.publicRaw);
  const s2 = await ecdhSharedSecret(b.privateKey, a.publicRaw);
  assert.equal(toHex(s1), toHex(s2));
  assert.equal(s1.length, 32);
});

test('algorithm constants describe what is implemented', () => {
  assert.equal(ALG.AUTH, 'HMAC-SHA-256-128');
  assert.equal(ALG.ENC, 'AES-128-CBC');
  assert.equal(ALG.ICV_LEN, 16);
});
